assert all(x['text'] in md for x in cm['paragraphs']);assert portable['paragraphs']==[x['text'] for x in cm['paragraphs']]
assert re.findall(r'\[\^(\d+)\](?!:)',md)==['1','2','3'];assert re.findall(r'^\[\^(\d+)\]:',md,re.M)==['1','2','3'];assert all(x['aggregate_words']<=x['target'] for x in budgets)
assert sha(repo/'projects/site/public/images/food/ou-khatta.webp')==pres['photo']['sha256'];assert all(x['href'] in md for x in pres['related'])
head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip()
checks={'status':'PASS','actual_head':head,'body_paragraphs':6,'lead_separate':True,'body_words':sum(len(re.sub(r'\[\^\d+\]','',x['text']).split()) for x in cm['paragraphs']),'footnotes':3,'markers':3,'portable_exact_paragraph_parity':True,'photo_hash_exact':True,'all_three_existing_reading_links_preserved':True,'aggregate_website_plus_portable_budgets':[x['aggregate_words'] for x in budgets],'no_source_fetch':True};put('checks.json',checks)
inputs={str(f.relative_to(root)):sha(f) for f in [old/'report.json',old/'primary-web-evidence.json',old/'source-observations.json',root/'outputs/ou-khatta-readiness-2026-11-04/delivery.json',repo/'kb/reference/article-editorial-standard.md',repo/'kb/research/food/collection.json',repo/'kb/research/food/ou-khatta.md',repo/'kb/research/food/everyday-stories.json']}
put('report.json',{'status':'FROZEN_COMPLETE_DRAFT_PENDING_SEPARATE_REVIEW','article_id':'POD-EDIT-112','route':'/food/ou-khatta/','input_head':head,'reader_question':'How does this sour fruit become different accompaniments in one cook’s hands, and what place can the bowl occupy in a remembered meal?','substantive_change':'Replaces invitation-heavy eight-paragraph sketch with a six-paragraph narrative: precooking/draining and second-pan sequence; whole-seed versus separate mustard–cumin paste; optional texture choice; specific banana-leaf meal arrangement, attributed to one family. Original comparative framing connects process and meal without invented observation.','source_basis':'Exactly three previously inspected primary captures; no new retrieval. Two recipes are one cook, not independent household evidence.','counts':checks,'budgets':budgets,'budget_scope':'Counts actual website plus proposed portable repetition, complete notes and short portable titles. Shared one-author sentence charged to both recipe sources. Lead and remaining reflection are original editorial framing. No other authored public route located for these IDs/URLs. Old same-route paragraphs are replaced, not appended; research indexes/source records are identified separately in reuse-inventory, not silently claimed as absent.','preservation':{'save_id':'food:ou-khatta','photo':'Existing Subhashish Panigrahi CC BY-SA 4.0 photo and alteration notice unchanged; not identified as either recipe or memoir kitchen.','links':'All three existing food reading links retained; shared journey/update controls must remain in implementation.'},'limits':['Not a tested recipe or field interview; no quantities/timings/medical/storage advice.','No statewide Kartik custom or vegetarian assertion adopted.','No new origin/current availability/district claim.','Unresolved Assam/Odisha university evidence omitted unchanged.','No canonical changes, build, publication, programme credit or new image.','Portable schema/implementation and independent draft review still required.'], 'input_bindings':inputs,'output_bindings':{n:sha(p/n) for n in ['article.md','claim-map.json','source-word-budgets.json','preservation.json','portable-plan.json','reuse-inventory.json','checks.json']}})
for n in ['article.md','report.json','claim-map.json','source-word-budgets.json']:print(n,sha(p/n))

